        for _n in qemu osmocon mobile bts sidecar-mobile; do
            _cible="$LOG_DIR/$_n.log"; _lien="/root/$_n.log"
            if [ -e "$_lien" ] && [ ! -L "$_lien" ]; then
                mod_say "⚠ /root/$_n.log est un vrai fichier — laissé en place"
