_fenetre_shell() {
    local aide=""
    local l; for l in "$@"; do aide="${aide}  ${l}\\n"; done
    _w shell "shell | depot qosmo-grgsm" \
        "cd '${QEMU_TREE:-.}' && printf '\n  %s\n  %s\n${aide}\n' \
             'etat  : ./run.sh --status' 'arret : ./run.sh --stop' \
